    if (this.shieldBlocks(e, vx, s.y)) {                              // glances off the riot shield
      s.body.setVelocity(-vx * 0.9, vy - 80); this.fxSparks(s.x, s.y, 8, Math.atan2(-vy, -vx), 1.4, [80, 240]); Sfx.clang(); return;
    }
