        if (!e.climbAtk && (up > 52 || b.blocked.up)) { b.setAllowGravity(true); b.velocity.y = 0; this.grinderBounce(e, wx); e.ai = ++e.bounces > T.bounces[i3] ? 'brake' : 'roll'; }   // a real wall after all
