        if ((e.tx - b.center.x) * ux + (e.ty - b.center.y) * uy < 4 || now >= e.aiUntil) { e.ai = 'recover'; e.aiUntil = now + 650 / fz; this.shake(160, 0.006); b.velocity.y = 0; }   // past the mark
