        if (now >= e.aiUntil) { if (--e.grid.left > 0) { this.overseerGridSet(e); e.ai = 'gridTell'; e.aiUntil = now + T.gridTell * 800; Sfx.alarm(); } else { e.grid = null; e.ai = 'hover'; e.cd = T.cd / rage; } }
        break;
