    for (const q of this.props) if (q !== p && q.st === 'ok' && Math.abs(q.cx - p.x) < q.hw + 12 && Math.abs(q.cy - (fy - 8)) < q.hh + 10) this.hitProp(q, 30, 'crush', q.cx, q.cy, Math.sign(q.cx - p.x) || 1, -0.5);
