      const d = Math.hypot(x - sx, y - sy); if (d > T.range) return;
      let da = Math.abs(Math.atan2(y - sy, x - sx) - a) % (Math.PI * 2); if (da > Math.PI) da = Math.PI * 2 - da;
      if (da > T.cone && d > 14) return;
