      for (const s of [-1, 1]) g.lineStyle(1, 0x9a70ff, al).lineBetween(mx, my, mx + Math.cos(a + s * T.cone) * T.range * 0.8, my + Math.sin(a + s * T.cone) * T.range * 0.8);
