    this.fx.emit(x, y - 2, { n: 16, angle: -Math.PI / 2, spread: Math.PI * 1.4, speed: [50, 170], life: [0.3, 0.7], size: [2, 1], cols: [0xffffff, 0xd8f4ff, 0x9ad0f0, 0x5a90c0], g: 600, mode: 1, cosmetic: true });
