    if (e.def.mech) this.fxSparks(S.x, S.y, 8, S.a + Math.PI, 1.2); else { this.fxBlood(S.x, S.y, 10, S.a, 0.7, [100, 300]); this.fxBlood(S.x, S.y, 4, S.a + Math.PI, 1, [40, 120]); }
