    if (alive && !e.aggro && e.sees && dist < D.sight) { this.alertEnemy(e, now); Sfx.charge(0.3); }
    if (e.aggro && e.sees) e.aggroT = Math.max(e.aggroT, 3);
    if (e.aggro && (e.aggroT <= 0 || !alive)) e.aggro = false;
    let tx, ty;
